create function public.review_pa28_batch6_graph() returns integer
language plpgsql security definer set search_path=pg_catalog,public as $$
declare item jsonb; reference jsonb; v uuid; source_id uuid; model_id uuid; ref_id uuid; model_name text; count_rows integer:=0;
begin
 perform pg_advisory_xact_lock(hashtextextended('review-pa28-batch6',0));
 for item in select value from jsonb_array_elements($review$[
  {"type":"AD","number":"2024-14-03","hash":"c7be1903331497057fb55faf9ed5994e61774d8acd287cbbc1cb0da5df423b89","published_url":"https://www.govinfo.gov/content/pkg/FR-2024-07-16/pdf/2024-15529.pdf","models":["PA-28-140","PA-28-181"],"page":3,"excerpt":"Table 1 on physical PDF page 3 lists PA-28-140 and PA-28-181. Paragraph (c) limits applicability to a Garmin GFC 500 system that includes the optional GSA 28 pitch trim servo, installed under STC SA01866WI using Master Drawing List revisions 1 through 76.","conditions":{"equipment_key":"GARMIN:GFC500-GSA28-PITCH-TRIM","equipment_scope":"Garmin GFC 500 Autopilot System including the optional GSA 28 pitch trim servo, installed under STC SA01866WI using MDL 005-01264-00 revisions 1 through 76.","software":"Physical PDF page 5 requires a version later than 8.01 for G5, later than 9.01 for G3X Touch, or later than 2.59 for GI 275. Display/controller type and installed software require review.","compliance":"Profile equipment is user reported. STC/MDL configuration, software version, completed update and aircraft records require review.","publication":"Final published rule, 89 FR 57721-57725, FR document 2024-15529."},"references":[{"authority":"GARMIN","kind":"appliance_model","key":"GARMIN:GFC500-GSA28-PITCH-TRIM","label":"Garmin GFC 500 with optional GSA 28 pitch trim servo","relationship":"affects_component","page":3,"excerpt":"Paragraph (c) identifies the installed GFC 500 and optional GSA 28 pitch trim servo configuration that controls applicability.","conditions":{"configuration":"GFC 500 with optional GSA 28 pitch trim servo; STC, MDL revision and software predicates also apply."}},{"authority":"FAA","kind":"certificate","key":"STC:SA01866WI","label":"STC SA01866WI","page":3,"excerpt":"Paragraph (c) requires the GFC 500 configuration to be installed under STC SA01866WI using MDL 005-01264-00 revisions 1 through 76.","conditions":{"reference_role":"Installation-approval predicate. This edge does not establish installation on an individual aircraft."}},{"authority":"GARMIN","key":"MSB:22123:A:2023-01-03","label":"Garmin Mandatory STC Service Bulletin 22123 Rev A - January 3, 2023","page":5,"excerpt":"Note 1 states that the software update can be done using Garmin Mandatory STC Service Bulletin 22123, Revision A, dated January 3, 2023.","conditions":{"reference_role":"Update method identified by the AD; the AD also permits other software versions outside its prohibited ranges. Bulletin text was not retrieved."}}]},
  {"type":"AD","number":"2022-03-15","hash":"a2992fd94cb167d69195285d0d8578e939faa89df9ee7abbba05f3c27da4397c","published_url":"https://www.govinfo.gov/content/pkg/FR-2022-02-14/pdf/2022-03000.pdf","models":["PA-28-140","PA-28-181"],"page":6,"excerpt":"The Piper row in Table 1 on physical PDF page 6 includes PA-28-140 and PA-28-181. Paragraph (c) on physical page 3 requires one of two specified Garmin display/STC configurations interfaced through a GEA 24 to resistive fuel probes.","conditions":{"equipment_key":"GARMIN:G3X-GI275-GEA24-RESISTIVE-FUEL","equipment_scope":"Either G3X Touch under STC SA01899WI and MDL 005-01320-00 revision 9 or earlier, or GI 275 MFD under STC SA02658SE and MDL revision 9 or earlier; either path must use a GEA 24 connected to resistive fuel probes.","serial_scope":"All aircraft serial numbers in the model table, but only with one of the specified installed configurations.","compliance":"Profile equipment is user reported. Display, STC, MDL revision, GEA 24 interface, probe type, modification and records require review.","publication":"Final published rule, 87 FR 8157-8167, FR document 2022-03000."},"references":[{"authority":"GARMIN","kind":"appliance_model","key":"GARMIN:G3X-GI275-GEA24-RESISTIVE-FUEL","label":"Garmin G3X Touch or GI 275 with GEA 24 resistive-fuel interface","relationship":"affects_component","page":3,"excerpt":"Paragraph (c) identifies two alternative display/STC paths, each interfaced with a Garmin GEA 24 connected to resistive fuel probes.","conditions":{"configuration":"G3X Touch/SA01899WI OR GI 275/SA02658SE; both alternatives require an eligible MDL revision and a GEA 24 resistive-fuel-probe interface."}},{"authority":"FAA","kind":"certificate","key":"STC:SA01899WI","label":"STC SA01899WI","page":3,"excerpt":"Paragraph (c)(1) identifies the G3X Touch installation under STC SA01899WI as one alternative applicability path.","conditions":{"reference_role":"Alternative G3X approval path; installation and the remaining configuration predicates are not established."}},{"authority":"FAA","kind":"certificate","key":"STC:SA02658SE","label":"STC SA02658SE","page":3,"excerpt":"Paragraph (c)(2) identifies the GI 275 installation under STC SA02658SE as the other alternative applicability path.","conditions":{"reference_role":"Alternative GI 275 approval path; installation and the remaining configuration predicates are not established."}},{"authority":"GARMIN","key":"MSB:2134:A:2021-04-23","label":"Garmin Mandatory STC Service Bulletin 2134 Rev A - April 23, 2021","page":9,"excerpt":"Paragraph (g) requires the applicable modification instructions in Garmin Mandatory STC Service Bulletin 2134, Revision A, or 2135, Revision A.","conditions":{"reference_role":"G3X Touch modification path; choose the bulletin applicable to the installed STC configuration. Bulletin text was not retrieved."}},{"authority":"GARMIN","key":"MSB:2135:A:2021-04-23","label":"Garmin Mandatory STC Service Bulletin 2135 Rev A - April 23, 2021","page":9,"excerpt":"Paragraph (g) requires the applicable modification instructions in Garmin Mandatory STC Service Bulletin 2134, Revision A, or 2135, Revision A.","conditions":{"reference_role":"GI 275 modification path; choose the bulletin applicable to the installed STC configuration. Bulletin text was not retrieved."}}]},
  {"type":"AD","number":"2001-23-17","hash":"1b1ed4420e7fd3d8ddefcbac6f7310bcf1c64afeb80bb324b28180cbd517b8a1","published_url":"https://www.govinfo.gov/content/pkg/FR-2001-12-03/pdf/01-29325.pdf","legacy_publication":true,"models":["PA-28-140","PA-28-181"],"page":3,"excerpt":"The Piper row on physical PDF page 3 includes PA-28-140 and PA-28-181. Applicability is limited by paragraph (a)(1) on physical page 2 to Garmin GNS 430 P/N 011-00280-00 units with the specifically listed serial numbers.","conditions":{"equipment_key":"GARMIN:GNS430-011-00280-00-AFFECTED-SERIALS","equipment_scope":"Garmin GNS 430 P/N 011-00280-00 with one of the individual serials listed on physical PDF page 2 or serial 96301296 through 96303200. The aircraft table is not exclusive because field-approved installations may exist.","compliance":"Profile equipment is user reported. Unit part/serial identity, circuitry modification, prior work and aircraft records require review.","publication":"Final published rule, 66 FR 60140-60142, FR document 01-29325."},"references":[{"authority":"GARMIN","kind":"appliance_model","key":"GARMIN:GNS430-011-00280-00-AFFECTED-SERIALS","label":"Garmin GNS 430 P/N 011-00280-00 - affected serials","relationship":"affects_component","page":2,"excerpt":"Paragraph (a)(1) identifies GNS 430 P/N 011-00280-00 and the affected individual serials plus range 96301296 through 96303200.","conditions":{"part_scope":"P/N 011-00280-00 and an exact listed unit serial; a generic GNS 430 installation is insufficient."}},{"authority":"GARMIN","key":"SB:9905:A:1999-09-17","label":"Garmin Service Bulletin 9905 Rev A - September 17, 1999","page":3,"excerpt":"Paragraphs (d) and (h) require the circuitry modification in accordance with Garmin Service Bulletin 9905, Revision A, dated September 17, 1999.","conditions":{"reference_role":"Incorporated modification instructions. Bulletin text was not retrieved, and completed work is not inferred."}}]}
 ]$review$::jsonb) loop
  select dv.id into v from public.document_versions dv join public.documents d on d.id=dv.document_id
   where d.authority='FAA' and d.document_type='AD' and d.document_number=item->>'number' and dv.content_sha256=item->>'hash'
    and dv.status='current' and dv.is_published and d.is_published and dv.metadata->>'original_source_url'=item->>'published_url'
    and dv.metadata->>'original_source_kind'='final_federal_register'
    and exists(select 1 from public.related_document_matches match where match.version_id=dv.id and match.is_active) limit 1;
  if v is null then raise exception 'Verified current publication missing'; end if;
  insert into public.catalog_entities(authority,entity_type,natural_key,label,is_published) values('FAA','certificate','AD:'||(item->>'number'),'AD '||(item->>'number'),true)
   on conflict(authority,entity_type,natural_key) do update set is_published=true returning id into source_id;
  for model_name in select jsonb_array_elements_text(item->'models') loop
   select id into model_id from public.catalog_entities where authority='FAA' and entity_type='aircraft_model' and natural_key=model_name;
   if model_id is null or not exists(select 1 from public.related_document_matches where version_id=v and model=model_name and is_active) then raise exception 'Current model index missing'; end if;
   insert into public.relationships(source_entity_id,target_entity_id,relationship_type,evidence_version_id,evidence_page,evidence_excerpt,applicability_conditions,review_status,is_published)
    select source_id,model_id,'applies_to',v,(item->>'page')::integer,item->>'excerpt',item->'conditions','reviewed',true
    where not exists(select 1 from public.relationships where source_entity_id=source_id and target_entity_id=model_id and evidence_version_id=v and relationship_type='applies_to');
   count_rows:=count_rows+1;
  end loop;
  for reference in select value from jsonb_array_elements(item->'references') loop
   insert into public.catalog_entities(authority,entity_type,natural_key,label,is_published)
    values(reference->>'authority',coalesce(reference->>'kind','service_document'),reference->>'key',reference->>'label',true)
    on conflict(authority,entity_type,natural_key) do update set is_published=true returning id into ref_id;
   insert into public.relationships(source_entity_id,target_entity_id,relationship_type,evidence_version_id,evidence_page,evidence_excerpt,applicability_conditions,review_status,is_published)
    select source_id,ref_id,coalesce(reference->>'relationship','references'),v,(reference->>'page')::integer,reference->>'excerpt',reference->'conditions','reviewed',true
    where not exists(select 1 from public.relationships where source_entity_id=source_id and target_entity_id=ref_id and evidence_version_id=v and relationship_type=coalesce(reference->>'relationship','references'));
   count_rows:=count_rows+1;
  end loop;
 end loop;
 return count_rows;
end $$;
revoke all on function public.review_pa28_batch6_graph() from public,anon,authenticated;
grant execute on function public.review_pa28_batch6_graph() to service_role;
